  // Logika spec var representing port state for outgoing data port
  @spec var fault: Mining_Threat_Retreat_Supervisor.Fault_Fact = $

  def put_fault(value : Mining_Threat_Retreat_Supervisor.Fault_Fact) : Unit = {
    Contract(
      Modifies(fault),
      Ensures(
        fault == value
      )
    )
    Spec {
      fault = value
    }

    Art.putValue(fault_Id, Mining_Threat_Retreat_Supervisor.Fault_Fact_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

